    /// ```
    /// use canopy::{ChildSlot, Widget, slot};
    ///
    /// slot!(Editor);
    /// impl Widget for Editor {}
    ///
    /// pub struct Modal;
    /// impl Widget for Modal {}
    /// slot!(pub ModalSlot: Modal);
