        /// Invoke only the specified command owner.
        fn dispatch_exact(
            &mut self,
            node: NodeId,
            command: &CommandInvocation,
        ) -> StdResult<ArgValue, CommandError> {
        }

        /// Get or create the keyed child under the current node.
